import numpy as npfrom scipy.integrate import quadR_SUN = 8.33RHO_SUN = 0.3RHO_S = 24.42R_S = 0.184R_0 = 0.5S_MAX = 200.0def rho_nfw(r):    if r == 0: return np.inf    return RHO_S * (R_S / r) * (1.0 / (1.0 + r / R_S)**2)def rho_cored(r):    return RHO_S * (R_S / (r + R_0)) * (1.0 / (1.0 + r / R_S)**2)def get_r(s, theta):    return np.sqrt(R_SUN**2 + s**2 - 2.0 * R_SUN * s * np.cos(theta))def j_los(theta, profile_func):    integrand = lambda s: (profile_func(get_r(s, theta)) / RHO_SUN)**2    j_val, _ = quad(integrand, 0.0, S_MAX, limit=100)    return j_val / R_SUNdef j_averaged_annulus(theta_min, theta_max, profile_func):    # Delta Omega per un annulus [theta_min, theta_max]    delta_omega = 2.0 * np.pi * (np.cos(theta_min) - np.cos(theta_max))    integrand = lambda theta: 2.0 * np.pi * np.sin(theta) * j_los(theta, profile_func)    integral_val, _ = quad(integrand, 0.0, theta_max, limit=50)    return integral_val / delta_omegadef main():    print("--- QUESTION 3: Analisi Errore Annulus HESS [0.3°, 1°] ---")    theta_min = np.radians(0.3)    theta_max = np.radians(1.0)        # Calcolo dei J-factor mediati nell'annulus    j_hess_nfw = j_averaged_annulus(theta_min, theta_max, rho_nfw)    j_hess_core = j_averaged_annulus(theta_min, theta_max, rho_cored)        error_factor = j_hess_nfw / j_hess_core        print(f"J_bar (NFW puro)   = {j_hess_nfw:.2f}")    print(f"J_bar (Con Core)   = {j_hess_core:.2f}")    print(f"Fattore di sovrastima del J-factor: {error_factor:.2f}")    print(f"\nConclusione:")    print(f"Se HESS assume un profilo NFW puro ma la Galassia ha un core di {R_0} kpc,")    print(f"il J-factor viene sovrastimato di un fattore {error_factor:.1f}.")    print(f"Di conseguenza, il limite superiore (upper bound) sulla sezione d'urto")    print(f"risulta artificialmente PIÙ STRINGENTE di circa {error_factor:.1f} volte rispetto al vero.")if __name__ == "__main__":    main()